'use strict';
const poems=window.POETRY_DATA||[], meta=window.POETRY_META||{};
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const grades=['全部年级','一年级','二年级','三年级','四年级','五年级','六年级','七年级','八年级','九年级','高一','高二','高三'];
const initial={favorites:[],mastered:[],visited:[],wrong:[],answers:{},last:null};
let profile;
try{profile={...initial,...JSON.parse(localStorage.getItem('shiguang-profile-v1')||'{}')}}catch{profile={...initial}}
for(const key of ['favorites','mastered','visited','wrong'])if(!Array.isArray(profile[key]))profile[key]=[];
if(!profile.answers||typeof profile.answers!=='object')profile.answers={};
let savedCurriculum='all';try{savedCurriculum=localStorage.getItem('shiguang-curriculum')||'all'}catch{}
let state={kind:'all',curriculum:['all','sixThree','fiveFour'].includes(savedCurriculum)?savedCurriculum:'all',edition:'全部',addedOnly:false,grade:0,semester:'全部',book:'全部',status:'全部',theme:'全部',search:'',studyFilter:'favorites',tab:'read',translationMode:'line',gloss:true,pinyin:true,cover:false,revealed:new Set(),speechRate:.8,quiz:null};
for(const p of poems)if(!p.kind)p.kind='poetry';
const poemMap=new Map(poems.map(p=>[p.id,p]));
const qMap=new Map(poems.flatMap(p=>p.questions.map(q=>[q.id,{...q,poem:p}])));
for(const key of ['favorites','mastered','visited'])profile[key]=[...new Set(profile[key].filter(id=>poemMap.has(id)))];
profile.wrong=[...new Set(profile.wrong.filter(id=>qMap.has(id)))];
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700)}
function save(){try{localStorage.setItem('shiguang-profile-v1',JSON.stringify(profile))}catch{toast('浏览器无法保存记录，本次仍可继续学习。')}$('#wrong-count').textContent=profile.wrong.length}
function toggle(arr,id){const i=arr.indexOf(id);i<0?arr.push(id):arr.splice(i,1)}
function currentPoem(){return poemMap.get(decodeURIComponent(location.hash.split('/')[1]||''))}
function stopSpeech(){if('speechSynthesis'in window)window.speechSynthesis.cancel()}
const systemNames={sixThree:'六三制',fiveFour:'五四制',common:'高中通用'};
function stage(grade){return grade<=(state.curriculum==='fiveFour'?5:6)?'小学':grade<=9?'初中':'高中'}
function memberships(p){return (p.curricula||[]).filter(c=>(state.curriculum==='all'||c.system===state.curriculum||c.system==='common')&&(state.edition==='全部'||c.system!=='fiveFour'||c.grade!==6||(state.edition==='既有版'?!c.edition.includes('2024'):c.edition.includes('2024'))))}
function placement(p){const list=memberships(p),grade=state.grade||(state.curriculum==='all'?p.grade:0);return list.find(c=>(!grade||c.grade===grade)&&(state.semester==='全部'||c.semester===state.semester))||list[0]||{grade:p.grade,semester:p.semester,book:p.book,system:'',edition:'拓展阅读'};}
function inScope(p,g=state.grade){if(state.kind!=='all'&&p.kind!==state.kind)return false;const list=memberships(p);return (list.length>0||state.curriculum==='all')&&(!g||(list.length?list.some(c=>c.grade===g):p.grade===g));}
function curriculumControl(){return `<div class="curriculum-bar"><div><span class="curriculum-label">山东教材 · 按学制选读</span><div class="curriculum-switch" role="group" aria-label="选择学制">${[['all','全部教材'],['sixThree','六三制'],['fiveFour','五四制']].map(([v,t])=>`<button data-action="curriculum" data-value="${v}" class="${state.curriculum===v?'active':''}" aria-pressed="${state.curriculum===v}">${t}</button>`).join('')}</div></div><div class="curriculum-options">${state.curriculum==='fiveFour'?`<label>六年级版本<select id="edition-filter" aria-label="五四制六年级教材版本">${['全部','既有版','2024修订版'].map(v=>`<option value="${v}" ${state.edition===v?'selected':''}>${v==='全部'?'两版合并':v}</option>`).join('')}</select></label>`:''}<button class="pill ${state.addedOnly?'active':''}" data-action="added-only" aria-pressed="${state.addedOnly}">山东补收 ${(meta.shandong?.added||0)+(meta.shandong?.proseAdded||0)} 篇诗文</button></div></div><p class="curriculum-hint">${state.curriculum==='fiveFour'?'五四制：小学一至五年级，初中六至九年级；同一首诗可能出现在不同册次。':'六三制：小学一至六年级，初中七至九年级。'} 编排随版本调整，可在篇目内查看各版归属与来源。</p>`;}
function contentTypeControl(){return `<div class="content-type-bar"><div><h2>古诗与古文，一起读懂。</h2><p>按年级选篇，也可以专门练习文言文。</p></div><div class="content-type-switch" role="group" aria-label="选择内容类型">${[['all','全部诗文'],['poetry','古诗词'],['prose','文言文']].map(([k,t])=>`<button data-action="content-type" data-value="${k}" class="${state.kind===k?'active':''}" aria-pressed="${state.kind===k}">${t}<span>${poems.filter(p=>k==='all'||p.kind===k).length}</span></button>`).join('')}</div></div>`;}
function isProse(p){return p.kind==='prose'}
function textUnit(p){return isProse(p)?'句子':'诗句'}
function startId(list){const last=poemMap.get(profile.last);return last&&list.some(p=>p.id===last.id)?last.id:list.find(p=>p.title==='咏鹅')?.id||list[0]?.id||poems[0]?.id}
function fullMeaning(p){return isProse(p)?'全文译文':'全诗意思'}
function metrics(){return `<div class="metrics"><div class="metric"><span class="metric-icon">册</span><div><strong>${poems.length}</strong><small>诗文篇目索引</small></div></div><div class="metric"><span class="metric-icon">字</span><div><strong>${poems.filter(p=>isProse(p)).length}</strong><small>文言文篇目</small></div></div><div class="metric"><span class="metric-icon">练</span><div><strong>${qMap.size}</strong><small>配套原创练习</small></div></div><div class="metric"><span class="metric-icon">✓</span><div><strong>${profile.mastered.length}</strong><small>已经背会的篇目</small></div></div></div>`}
function nav(){const end=state.curriculum==='fiveFour'?5:6,groups=[[1,end,'小学 · 亲近诗文'],[end+1,9,'初中 · 理解古文'],[10,12,'高中 · 读懂经典']];$('#grade-nav').innerHTML=`<p class="nav-curriculum">${state.curriculum==='all'?'全部诗文':systemNames[state.curriculum]+'教材'}</p><a class="all-grades ${state.grade===0?'active':''}" href="#library" data-grade="0">全部年级 <small>${poems.filter(p=>inScope(p,0)).length}</small></a>`+groups.map(([a,b,t])=>`<div class="stage-title">${t}</div><div class="grade-links">${Array.from({length:b-a+1},(_,i)=>{const g=a+i;return `<a href="#grade/${g}" data-grade="${g}" class="${g===state.grade?'active':''}">${grades[g]}<small>${poems.filter(p=>inScope(p,g)).length}</small></a>`}).join('')}</div>`).join('');$('#wrong-count').textContent=profile.wrong.length}
function card(p){const c=placement(p),systems=[...new Set((p.curricula||[]).map(x=>systemNames[x.system]))];return `<article class="poem-card"><div class="card-kicker"><span>${grades[c.grade]} · ${c.grade>9?esc(c.book):esc(c.semester)}</span>${profile.mastered.includes(p.id)?'<span class="learned">✓ 已背会</span>':''}</div><button class="star ${profile.favorites.includes(p.id)?'on':''}" data-action="favorite" data-id="${p.id}" aria-label="${profile.favorites.includes(p.id)?'取消收藏':'收藏'}${esc(p.title)}" aria-pressed="${profile.favorites.includes(p.id)}">${profile.favorites.includes(p.id)?'★':'☆'}</button><h3><a href="#poem/${p.id}">${esc(p.title)}</a></h3><div class="card-author">〔${esc(p.dynasty)}〕${esc(p.author)}</div><div class="curriculum-tags"><span class="genre-tag">${isProse(p)?'文言文':'古诗词'}</span>${systems.map(t=>`<span>${t}</span>`).join('')||'<span>拓展阅读</span>'}${p.shandongAdded?'<span class="new-poem">新补收</span>':''}</div><p class="card-verse">${p.lines.slice(0,2).map(esc).join('<br>')||'现代诗词 · 教材篇目索引'}</p><div class="card-bottom"><span class="tag">${esc(p.theme)}</span><span>${p.copyright?'短摘录 · 来源链接':`拼音 · 注释 · ${p.questions.length}道题`}</span><span class="card-arrow">↗</span></div></article>`}
function empty(title,description){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(description)}</p><a class="btn secondary" href="#library">浏览诗文库</a></div>`}
function filtered(){const query=state.search.trim().toLowerCase();return poems.filter(p=>inScope(p)&&(!state.addedOnly||p.shandongAdded)&&(state.semester==='全部'||memberships(p).some(c=>(!state.grade||c.grade===state.grade)&&c.semester===state.semester)||(!p.curricula?.length&&p.semester===state.semester))&&(state.book==='全部'||p.book===state.book)&&(state.theme==='全部'||p.theme===state.theme)&&(state.status==='全部'||(state.status==='已背会'?profile.mastered.includes(p.id):!profile.mastered.includes(p.id)))&&(!query||[p.title,p.author,p.dynasty,p.theme,...p.lines,...p.notes.map(n=>n.word)].join(' ').toLowerCase().includes(query)))}
function library(){const list=filtered(),g=state.grade;const scoped=poems.filter(p=>inScope(p,g));const themes=[...new Set(scoped.map(p=>p.theme))];const books=[...new Set(scoped.filter(p=>p.grade>9).map(p=>p.book))];$('#main').innerHTML=`<section class="hero"><div class="hero-copy"><p class="eyebrow">A LITTLE POETRY, EVERY DAY</p><h1>从诗词到文言，<br>读懂古人的话。</h1><p class="intro">循着年级，读诗词，也读古文。<br>识拼音、解字词、看译文，让背诵成为理解的开始。</p><a class="btn" href="#poem/${startId(list)}">${profile.last===startId(list)?'继续上次学习':'开始读一篇'} <span>↗</span></a></div><svg class="hero-art" viewBox="0 0 600 320" preserveAspectRatio="xMidYMax slice" aria-hidden="true"><defs><linearGradient id="mist" x2="0" y2="1"><stop stop-color="#bdcbb0" stop-opacity=".4"/><stop offset="1" stop-color="#e2ead9"/></linearGradient></defs><circle cx="383" cy="91" r="34" fill="#d7bf88" opacity=".55"/><path d="M0 254 60 194 96 213 154 118 207 195 262 148 304 208 357 158 389 197 432 154 483 212 551 173 600 198V320H0Z" fill="url(#mist)"/><path d="m0 306 99-84 45 35 100-64 85 63 65-42 83 53 63-33 70 43V320H0Z" fill="#bdccb1" opacity=".6"/><path d="M0 307q155-22 303-1t297-4" fill="none" stroke="#9eaf8d" opacity=".6"/><path d="m320 279 28 5-7 6h-33Z" fill="#7c926d" opacity=".7"/><path d="m329 259-1 23m2-23 9 18h-9" stroke="#7c926d" fill="none" stroke-width="1"/></svg><div class="vertical-verse">诗里有山河<br>心中有远方</div><span class="tiny-seal">诗光</span></section>${metrics()}${contentTypeControl()}${curriculumControl()}<section aria-label="古诗文目录"><div class="section-head"><div><h2>${g?grades[g]+(state.kind==='prose'?' · 文言文':state.kind==='poetry'?' · 古诗词':' · 古诗文'):'循级而读'}</h2><p>${state.search?'搜索结果 · 支持篇名、作者与原文':g>9?'高中年级为建议学习顺序，请按学校进度和教材册次选读。':'选择一个年级，把每篇诗文慢慢读懂。'}</p></div><button class="btn secondary" data-action="start-quiz">本页随机练习 ↗</button></div><div class="filters"><div class="pill-row">${['全部','上册','下册'].map(s=>`<button class="pill ${state.semester===s?'active':''}" data-action="semester" data-value="${s}">${s==='全部'?'全部册次':s}</button>`).join('')}</div><div class="filter-controls">${g>9||!g?`<select id="book-filter" aria-label="教材册次"><option value="全部">高中教材册次</option>${books.map(b=>`<option ${state.book===b?'selected':''}>${esc(b)}</option>`).join('')}</select>`:''}<select id="theme-filter" aria-label="诗文主题"><option value="全部">全部主题</option>${themes.map(t=>`<option ${state.theme===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="status-filter" aria-label="背诵状态">${['全部','未背会','已背会'].map(s=>`<option ${s===state.status?'selected':''} value="${s}">${s==='全部'?'全部状态':s}</option>`).join('')}</select><span class="result-count">${list.length} 篇</span></div></div><div class="poem-grid">${list.length?list.map(card).join(''):empty('还没有找到这篇诗文','试试其他关键词，或清除册次、主题和背诵状态筛选。')}</div><div class="note-banner">收录基于统编教材既有篇目目录，采用版本见「收录范围与来源」。现代作者作品提供篇目索引和短摘录。配套练习为本站原创；教材课后原题、各地全部考题不在本库范围内。</div></section>`}
function poemSources(p){return `<details class="source-details"><summary>原文与释义参考来源</summary><p>教材编排见篇目上方的「各版教材归属」。字词注释和白话译文由本站整理编写。${p.variantNote?'<br>异文说明：'+esc(p.variantNote):''}</p>${(p.sources||[]).filter(u=>/^https?:\/\//.test(u)).map((u,i)=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">参考来源 ${i+1} · ${esc(new URL(u).hostname)} ↗</a>`).join('')}</details>`}
function detail(p){const c=p?placement(p):null;if(!p){$('#main').innerHTML=empty('这篇诗文暂未收录','请从年级目录选择已收录篇目。');return}$('#main').innerHTML=`<div class="breadcrumb"><a href="#library">诗文库</a><span>›</span><a href="#grade/${c.grade}">${grades[c.grade]}</a><span>›</span><span>${esc(c.book)}</span></div><div class="detail-title"><div><div class="eyebrow">${stage(c.grade)} · ${isProse(p)?'文言文 · ':''}${esc(p.theme)}${p.copyright?' · 现代篇目索引':''}</div><h1>${esc(p.title)}</h1>${p.titlePinyin?`<p class="title-pinyin">${esc(p.titlePinyin)}</p>`:''}<div class="meta">〔${esc(p.dynasty)}〕${esc(p.author)} · ${grades[c.grade]} · ${esc(c.book)}</div></div><div class="detail-actions"><button class="btn secondary" data-action="favorite" data-id="${p.id}">${profile.favorites.includes(p.id)?'★ 已收藏':'☆ 收藏'}</button><button class="btn ${profile.mastered.includes(p.id)?'light':'secondary'}" data-action="mastered" data-id="${p.id}">${profile.mastered.includes(p.id)?'✓ 已背会':'标记背会'}</button><button class="tool" data-action="print">打印</button></div></div>${curriculumAssignments(p)}<div class="detail-tabs" role="tablist" aria-label="学习内容">${[['read','原文 · 背诵'],['analysis','注释 · 译文'],['practice',`配套练习 (${p.questions.length})`]].map(([k,t])=>`<button role="tab" aria-selected="${state.tab===k}" class="${state.tab===k?'active':''}" data-action="tab" data-value="${k}">${t}</button>`).join('')}</div><div role="tabpanel">${state.tab==='read'?reading(p):state.tab==='analysis'?analysis(p):practice(p)}</div>`}
function curriculumAssignments(p){const all=p.curricula||[],names=[...new Set(all.map(c=>systemNames[c.system]))];return `<details class="curriculum-assignments"><summary><span>教材归属</span> ${names.map(esc).join(' / ')||'拓展阅读'}${p.shandongAdded?' · 本次补收':''}<small>查看年级与版本 ↓</small></summary>${all.length?`<ul>${all.map(c=>`<li><b>${esc(systemNames[c.system])} · ${grades[c.grade]}${c.grade<=9?' '+esc(c.semester):''}</b><span>${esc(c.grade>9?c.book:c.section)} · ${esc(c.edition)}</span><a href="${esc(c.source)}" target="_blank" rel="noopener noreferrer">目录来源 ↗</a></li>`).join('')}</ul>`:'<p>此篇保留为拓展学习，可按主题选读。</p>'}</details>`;}
function noteList(p,limit=p.notes.length){return `<dl class="numbered-notes">${p.notes.slice(0,limit).map((n,i)=>`<div class="annotation" id="note-${i+1}"><dt><span class="note-number">${i+1}</span>${esc(n.word)}${!p.lines.some(l=>l.includes(n.word))?`<small class="annotation-type">${p.title.includes(n.word)?'题义':'合并讲解'}</small>`:''}</dt><dd>${esc(n.meaning)}</dd></div>`).join('')}</dl>`;}
function rubyLine(p,line,i){let j=0;const marks=new Map(),ends=new Map();if(state.gloss&&!state.cover){p.notes.forEach((n,k)=>{let found=-1,pos=-1;for(let l=0;l<p.lines.length;l++){const at=p.lines[l].indexOf(n.word);if(at>=0){found=l;pos=Array.from(p.lines[l].slice(0,at)).length;break}}if(found===i){for(let nAt=pos;nAt<pos+Array.from(n.word).length;nAt++)if(!marks.has(nAt))marks.set(nAt,{...n,number:k+1});ends.set(pos+Array.from(n.word).length-1,k+1);}})}return line.split(/(?<=[，。！？；：、])/u).map(part=>'<span class="verse-clause">'+Array.from(part).map((c,ci,cs)=>{const at=j++,py=p.pinyin?.[i]?.[at]||'',note=marks.get(at),han=/\p{Script=Han}/u,punct=/^[，。！？；：、”’）]$/u;if(punct.test(c)&&han.test(cs[ci-1]||''))return '';const tail=han.test(c)&&punct.test(cs[ci+1]||'')?esc(cs[ci+1]):'';return han.test(c)?'<span class="han-unit"><ruby><span class="char '+(note?'gloss-word':'')+'"'+(note?' title="'+esc(note.word+'：'+note.meaning)+'"':'')+'>'+esc(c)+'</span><rt>'+esc(py)+'</rt></ruby>'+(ends.has(at)?'<sup class="verse-note" aria-label="注释'+ends.get(at)+'">'+ends.get(at)+'</sup>':'')+tail+'</span>':esc(c)}).join('')+'</span>').join('')}
function reading(p){return `<div class="reading-grid"><section class="panel"><div class="reading-tools"><button class="tool ${state.pinyin?'active':''}" data-action="pinyin" aria-pressed="${state.pinyin}">拼音 ${state.pinyin?'开':'关'}</button><button class="tool ${state.gloss?'active':''}" data-action="gloss" aria-pressed="${state.gloss}">注释标号 ${state.gloss?'开':'关'}</button>${!p.copyright?`<button class="tool ${state.cover?'active':''}" data-action="cover" aria-pressed="${state.cover}">${state.cover?'退出遮字':'遮字背诵'}</button>`:''}<button class="tool" data-action="speak">▷ 朗读</button><button class="tool" data-action="stop-speech" aria-label="停止朗读">□ 停止</button><select class="voice-rate" id="voice-rate" aria-label="朗读速度">${[[.65,'慢速'],[.8,'舒缓'],[1,'正常']].map(([v,t])=>`<option value="${v}" ${state.speechRate===v?'selected':''}>${t}</option>`).join('')}</select></div>${p.copyright?'<div class="note-banner" style="margin:0 0 25px">本篇为现代作者作品，提供现有短摘录、学习概要与原创练习。全文请阅读语文教材或下方来源。</div>':''}${p.textScope?`<p class="scope-note">${esc(p.textScope)}</p>`:''}${isProse(p)?`<p class="prose-reading-intro">按句阅读原文，用注释理解关键词，再对照白话译文。共 ${p.lines.length} 个学习句组。</p>`:''}${p.preface?`<details class="preface"><summary>小序 · 原文</summary><p class="prose">${esc(p.preface)}</p></details>`:''}<div class="poem-lines ${isProse(p)?'prose-lines':''} ${state.pinyin?'':'no-pinyin'}">${p.lines.map((line,i)=>`<button class="poem-line ${isProse(p)?'prose-line':''} ${state.cover&&!state.revealed.has(i)?'covered':''}" data-action="reveal" data-line="${i}" aria-label="${state.cover&&!state.revealed.has(i)?'显示第'+(i+1)+'行':esc(line)}">${rubyLine(p,line,i)}</button>`).join('')}</div><p class="reading-hint">${state.cover?'点击一行显示提示，再点击重新遮住。':'原文中的数字对应字词注释；悬停有下划线的词语可读释义。'}<br>理解文意，再遮字背诵。浏览器朗读的多音字请参照拼音。</p><div class="practice-callout"><span>把原文与白话译文对照着读。</span><button class="btn" data-action="tab" data-value="analysis">注释 · 逐句译文 →</button></div>${poemSources(p)}</section><aside><section class="panel"><div class="panel-heading"><h2>关键词注释</h2><span>${p.notes.length} 条</span></div>${noteList(p,8)}${p.notes.length>8?`<button class="text-button" data-action="tab" data-value="analysis">查看全部 ${p.notes.length} 条注释 →</button>`:''}</section><section class="panel"><h2>${p.copyright?'摘录意思 / 学习概要':fullMeaning(p)}</h2><p class="prose">${esc(p.translation.slice(0,320))}${p.translation.length>320?'……':''}</p><button class="text-button" data-action="tab" data-value="analysis">${p.translation.length>320?'阅读全文与逐句译文':'逐句对照 · 理解与赏析'} →</button></section></aside></div>`}
function analysis(p){return `<div class="annotation-intro"><span class="annotation-seal">释</span><div><h2>${isProse(p)?'读懂字词，也读懂整篇古文。':'读懂字词，也读懂整首诗。'}</h2><p>先看关键词，再把原句与白话意思逐行对照。注释与译文由本站整理编写。</p></div></div>${isProse(p)?'<div class="analysis-jumps" aria-label="文言文阅读定位"><button class="tool" data-action="analysis-jump" data-value="translation">看白话译文 ↓</button><button class="tool" data-action="analysis-jump" data-value="notes">查字词注释 ↓</button></div>':''}<div class="analysis-layout ${isProse(p)?'prose-analysis':''}"><section class="panel"><div class="panel-heading"><h2>字词注释</h2><span>${p.notes.length} 条</span></div>${noteList(p)}${poemSources(p)}</section><section class="panel"><div class="meaning-switch" role="group" aria-label="译文显示方式">${[['line',p.copyright?'摘录对照':'逐句译文'],['full',p.copyright?'学习概要':fullMeaning(p)]].map(([v,t])=>`<button class="${state.translationMode===v?'active':''}" data-action="translation-mode" data-value="${v}" aria-pressed="${state.translationMode===v}">${t}</button>`).join('')}</div>${state.translationMode==='line'&&p.lineTranslations?.length?`<ol class="line-translations">${p.lineTranslations.map((x,i)=>`<li><div class="translation-line-number">${i+1}</div><div><p class="translation-original">${esc(x.original)}</p><p class="translation-meaning">${esc(x.meaning)}</p></div></li>`).join('')}</ol>`:`<h2>${p.copyright?'摘录意思 / 学习概要':fullMeaning(p)}</h2><p class="prose full-translation">${esc(p.translation)}</p>`}${p.prefaceTranslation?`<details class="preface"><summary>小序 · 白话译文</summary><p class="prose">${esc(p.prefaceTranslation)}</p></details>`:''}<h2 class="analysis-heading">理解与赏析</h2><p class="prose">${esc(p.analysis)}</p><div class="insight">再读一遍，想一想：哪些词语最能表现「${esc(p.theme)}」？用具体${isProse(p)?'语句':'诗句'}支持你的理解。</div></section></div>`}
function question(q,p,{review=false,quiz=false}={}){const ans=profile.answers[q.id];const answered=Boolean(ans?.checked);const prefix=`${quiz?'quiz-':''}${q.id}`;return `<article class="question-card" data-question="${q.id}"><div class="question-top">${q.type==='choice'?(isProse(p)?'文言理解':'诗意理解'):q.type==='fill'?(isProse(p)?'原文默写':'诗句默写'):(isProse(p)?'翻译与理解':'赏析表达')} · ${esc(p.title)}</div><h3>${esc(q.prompt)}</h3>${q.type==='choice'?`<div class="options">${q.options.map((o,i)=>`<button class="option ${ans?.value===i?'selected':''} ${answered&&i===q.answer?'correct':''} ${answered&&ans.value===i&&!ans.correct?'incorrect':''}" data-action="choose" data-qid="${q.id}" data-value="${i}" ${answered?'disabled':''}><b>${'ABCD'[i]}</b><span>${esc(o)}</span></button>`).join('')}</div>`:`${q.type==='short'?`<textarea class="answer-input" id="${prefix}" data-answer="${q.id}" rows="3" placeholder="写下你的理解，再对照参考答案自评" aria-label="${esc(q.prompt)}" ${answered?'readonly':''}>${esc(ans?.value||'')}</textarea>`:`<input class="answer-input" id="${prefix}" data-answer="${q.id}" autocomplete="off" placeholder="填写原文（不计标点与空格）" aria-label="${esc(q.prompt)}" value="${esc(ans?.value||'')}" ${answered?'readonly':''}>`}`}${!answered?`<div class="answer-row"><button class="btn" data-action="check" data-qid="${q.id}">${q.type==='short'?'查看参考答案':'提交答案'}</button>${q.type==='short'?'<span>表达题使用自评，不自动判定。</span>':''}</div>`:''}${answered?`<div class="feedback ${ans.correct===false?'bad':''}"><strong>${q.type==='short'?'参考答案':ans.correct?'✓ 回答正确':'再读一遍，这里需要注意'}</strong>${q.type==='choice'?'答案：'+esc('ABCD'[q.answer])+' · '+esc(q.options[q.answer]):'参考答案：'+esc(q.answer)}<br>${esc(q.explanation)}${q.type==='short'&&ans.correct===null?`<div class="answer-row"><button class="btn" data-action="self-check" data-qid="${q.id}" data-value="true">我已掌握</button><button class="btn secondary" data-action="self-check" data-qid="${q.id}" data-value="false">加入错题</button></div>`:''}</div><div class="answer-row"><button class="text-button" data-action="retry" data-qid="${q.id}">再做一次</button>${review?`<button class="text-button" data-action="remove-wrong" data-qid="${q.id}">移出错题本</button>`:''}</div>`:''}</article>`}
function practice(p){const done=p.questions.filter(q=>profile.answers[q.id]?.checked&&profile.answers[q.id]?.correct!==null),correct=done.filter(q=>profile.answers[q.id].correct);return `<div class="practice-head"><p>每篇诗文配套原创练习 · 默写、理解与赏析</p><p>已完成 ${done.length}/${p.questions.length} · 正确 ${correct.length}</p></div>${p.questions.map(q=>question(q,p)).join('')}`}
function study(){const done=Object.values(profile.answers).filter(a=>a.checked&&a.correct!==null),correct=done.filter(a=>a.correct);const percent=poems.length?Math.round(profile.mastered.length/poems.length*100):0;let list=profile[state.studyFilter].map(id=>poemMap.get(id)).filter(Boolean);if(state.search)list=list.filter(p=>[p.title,p.author,...p.lines].join('').includes(state.search));$('#main').innerHTML=`<div class="study-title"><p class="eyebrow">YOUR POETRY JOURNEY</p><h1>把读过的诗文，留在心里。</h1><p>收藏、背诵状态和练习记录保存在当前浏览器中。换设备不会自动同步。</p></div>${metrics()}<div class="progress-overview"><section class="progress-panel"><h2>背诵足迹</h2><div class="progress-row"><span>已背会 ${profile.mastered.length} 篇</span><span>${percent}%</span></div><div class="progress-track"><div style="width:${percent}%"></div></div><p class="stat-note">记录自己的进度，每一篇都值得慢慢来。</p></section><section class="progress-panel"><h2>练习收获</h2><div class="progress-row"><span>已完成 ${done.length} 道</span><span>正确 ${correct.length} 道</span></div><div class="progress-track"><div style="width:${done.length?correct.length/done.length*100:0}%"></div></div><p class="stat-note">表达题对照参考答案自评后计入统计。</p></section></div><div class="section-head"><h2>我的诗文</h2><button class="text-button" data-action="export-progress">备份学习记录 ↓</button></div><div class="study-controls">${[['favorites','我的收藏'],['mastered','已经背会'],['visited','最近读过']].map(([v,t])=>`<button class="pill ${state.studyFilter===v?'active':''}" data-action="study-filter" data-value="${v}">${t} · ${profile[v].length}</button>`).join('')}<button class="text-button" data-action="import-progress" style="margin-left:auto">导入记录</button><input hidden type="file" id="progress-import" accept="application/json"></div><div class="poem-grid">${list.length?list.map(card).join(''):empty('诗文旅程，从这一篇开始','打开喜欢的诗文，点击收藏或标记背会，就能在这里找到它。')}</div>`}
function wrong(){const list=profile.wrong.map(id=>qMap.get(id)).filter(Boolean);$('#main').innerHTML=`<div class="wrong-header"><div class="study-title"><p class="eyebrow">REVISIT & REMEMBER</p><h1>再读一次，就记得更牢。</h1><p>选择题与默写题答错后自动收录；赏析表达题由你自评。</p></div>${list.length?'<button class="btn secondary" data-action="retry-wrong">重做全部错题</button>':''}</div><p class="result-count">共 ${list.length} 道待复习</p>${list.length?list.map(q=>`<div class="wrong-label">${grades[q.poem.grade]} · <a href="#poem/${q.poem.id}">${esc(q.poem.title)} ↗</a></div>${question(q,q.poem,{review:true})}`).join(''):empty('错题本还空着','去练习几道题，答错的题会自动保存在这里。')}`}
function quiz(){if(!state.quiz?.length){$('#main').innerHTML=empty('本轮练习已结束','回到诗词库，选择年级开始新的练习。');return}const questions=state.quiz.map(id=>qMap.get(id)).filter(Boolean),done=questions.filter(q=>profile.answers[q.id]?.checked&&profile.answers[q.id]?.correct!==null),correct=done.filter(q=>profile.answers[q.id].correct);$('#main').innerHTML=`<div class="breadcrumb"><a href="${state.grade?'#grade/'+state.grade:'#library'}">返回目录</a><span>›</span><span>随机练习</span></div><div class="study-title"><p class="eyebrow">READ, THINK, PRACTICE</p><h1>${grades[state.grade]} · 随机练习</h1><p>从当前筛选篇目抽取 ${questions.length} 道题，答错的题会自动进入错题本。</p></div><div class="quiz-summary"><strong>${done.length}/${questions.length}</strong><p>本轮已完成 · 正确 ${correct.length} 道<br>${done.length===questions.length?'本轮完成，做得很好。可以回到诗词库继续学习。':'读懂题意，再写下答案。'}</p></div>${questions.map(q=>question(q,q.poem,{quiz:true})).join('')}`}
function render({scroll=false}={}){const route=location.hash.slice(1).split('/')[0]||'library';const navView=route==='grade'||route==='poem'||route==='quiz'?'library':route;document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===navView));nav();if(route==='poem')detail(currentPoem());else if(route==='study')study();else if(route==='wrong')wrong();else if(route==='quiz')quiz();else library();if(scroll)window.scrollTo({top:0,behavior:'instant'})}
function loadRoute(){stopSpeech();const [route,id]=location.hash.slice(1).split('/');if(route==='main'){$('#main').focus();return}if(route==='grade'){state.grade=Math.min(12,Math.max(1,Number(id)||1));state.semester='全部';state.book='全部';state.theme='全部'}else if(route==='library'){state.grade=0}if(route==='poem'){const p=currentPoem();if(p){state.tab='read';state.cover=false;state.revealed.clear();profile.last=p.id;toggleVisited(p.id);save()}}document.body.classList.remove('menu-open');render({scroll:true})}
function toggleVisited(id){profile.visited=profile.visited.filter(x=>x!==id);profile.visited.unshift(id)}
function syncAnswers(){document.querySelectorAll('[data-answer]').forEach(el=>{const q=qMap.get(el.dataset.answer);if(q&&!profile.answers[q.id]?.checked)profile.answers[q.id]={value:el.value,checked:false}})}
function evaluate(q,value,correct){profile.answers[q.id]={value,checked:true,correct};if(correct===false&&!profile.wrong.includes(q.id))profile.wrong.push(q.id);if(correct===true)profile.wrong=profile.wrong.filter(id=>id!==q.id);save()}
function normalize(s){return String(s).replace(/[\s，。！？；：、,.!?;:“”‘’'"()（）—…]/g,'')}
function showSources(){const c=meta.counts||{};$('#source-content').innerHTML=`<p>按年级学习小学、初中与高中古诗词和文言文，也可选择山东使用的六三制或五四制编排。</p><h3>文言文收录</h3><p>当前收录 ${c.prose||0} 篇文言文与 ${c.poetry||0} 条诗词索引。文言文包含教材课文、教材节选及蒙学篇目；节选范围、年级和必修／选择性必修册次标注在详情页。</p><p>每篇文言文均有公版原文、拼音、关键词释义、逐句对照、全文白话、理解与原创练习。注释讲解古今词义、通假和典故，译文由本站整理编写。</p><h3>教材范围与版本</h3><p>六三制为小学一至六年级、初中七至九年级；五四制为小学一至五年级、初中六至九年级。五四制六年级分别列出既有版与2024修订版，可筛选比较。同一作品对应不同版本或册次时，详情页分别标注。</p><p>诗词延续原诗库，并保留 ${meta.shandong?.added||0} 篇山东与通用目录补收。文言文按本次核对目录整理；学校在用印次请以手头教材为准。高中年级为建议学习顺序，准确归属以教材册次为准。《寒菊》保留为拓展阅读。</p><h3>学习内容</h3><p>全库 ${poems.length} 条篇目，${c.notes} 条注释，${c.lineTranslations} 条逐句译文，${qMap.size} 道原创练习。释义和题目供理解与复习使用，配套题不是照录教材课后题或历年真题。</p><p>现代诗词作品只解释本站现有短摘录或提供学习概要。拼音经过多音字专项校正，请结合教材和教师指导；浏览器朗读可能与显示拼音不同。</p><h3>教材与目录来源</h3>${(meta.shandong?.sources||[]).map(x=>`<p><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a></p>`).join('')}<p><a href="https://basic.smartedu.cn/tchMaterial" target="_blank" rel="noopener noreferrer">国家中小学智慧教育平台：教材查询 ↗</a></p><p>每篇详情的「教材归属」与「原文与释义参考来源」提供相应原文、目录链接。</p><h3>学习记录</h3><p>收藏、背诵状态和错题保存在当前浏览器，可在「我的学习」备份和导入；网站公开访问不共享个人学习记录。内容整理日期：2026年10月5日。</p><button class="btn secondary" data-action="export-data">下载古诗文与题目数据 ↓</button>`;$('#source-dialog').showModal()}
function download(content,name){const blob=new Blob([content],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;syncAnswers();const {action,id,value,qid}=button.dataset;const p=currentPoem(),q=qMap.get(qid);const y=window.scrollY;
switch(action){case'analysis-jump':document.querySelector(value==='notes'?'.analysis-layout>.panel:first-child':'.analysis-layout>.panel:nth-child(2)')?.scrollIntoView({behavior:'smooth',block:'start'});return;case'content-type':state.kind=value;state.book='全部';state.theme='全部';state.addedOnly=false;break;case'curriculum':state.curriculum=value;state.edition='全部';state.semester='全部';state.book='全部';state.theme='全部';state.addedOnly=false;try{localStorage.setItem('shiguang-curriculum',value)}catch{}break;case'added-only':state.addedOnly=!state.addedOnly;break;case'gloss':state.gloss=!state.gloss;break;case'translation-mode':state.translationMode=value;break;case'menu':document.body.classList.toggle('menu-open');return;case'sources':showSources();return;case'close-source':$('#source-dialog').close();return;case'favorite':toggle(profile.favorites,id);save();break;case'mastered':toggle(profile.mastered,id);save();toast(profile.mastered.includes(id)?'又读会了一篇，已记录。':'已取消背会标记。');break;case'semester':state.semester=value;break;case'study-filter':state.studyFilter=value;break;case'tab':stopSpeech();state.tab=value;break;case'pinyin':state.pinyin=!state.pinyin;break;case'cover':state.cover=!state.cover;state.revealed.clear();break;case'reveal':if(!state.cover)return;{const n=Number(button.dataset.line);state.revealed.has(n)?state.revealed.delete(n):state.revealed.add(n)}break;
case'speak':if(!p)return;if(!('speechSynthesis'in window)){toast('当前浏览器不支持语音朗读，请阅读拼音。');return}stopSpeech();{const voices=speechSynthesis.getVoices();const voice=voices.find(v=>/zh-CN|cmn-CN/i.test(v.lang))||voices.find(v=>v.lang.startsWith('zh'));if(voices.length&&!voice){toast('没有找到中文语音，请在系统语音设置中添加中文。');return}const u=new SpeechSynthesisUtterance(p.title+'。'+p.author+'。'+p.lines.join(''));u.lang='zh-CN';if(voice)u.voice=voice;u.rate=state.speechRate;u.onerror=()=>toast('语音无法播放，请检查系统中文语音支持。');speechSynthesis.speak(u);toast('正在朗读，读音可参照拼音。')}return;case'stop-speech':stopSpeech();return;case'print':window.print();return;
case'choose':if(!q)return;profile.answers[qid]={value:Number(value),checked:false};save();break;case'check':if(!q)return;{const a=profile.answers[qid]?.value;if(q.type==='choice'&&typeof a!=='number'||q.type!=='choice'&&!String(a||'').trim()){toast('请先填写或选择答案。');return}evaluate(q,a,q.type==='short'?null:q.type==='choice'?a===q.answer:normalize(a)===normalize(q.answer))}break;
case'self-check':if(!q)return;evaluate(q,profile.answers[qid]?.value,value==='true');break;case'retry':delete profile.answers[qid];save();break;case'remove-wrong':profile.wrong=profile.wrong.filter(x=>x!==qid);save();break;case'retry-wrong':profile.wrong.forEach(id=>delete profile.answers[id]);save();toast('已清除这些题的作答，可以重新练习。');break;
case'start-quiz':{const pool=filtered().flatMap(p=>p.questions.map(q=>q.id));if(!pool.length){toast('当前没有可练习的篇目，请调整筛选。');return}for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}state.quiz=pool.slice(0,10);state.quiz.forEach(id=>delete profile.answers[id]);save();location.hash='quiz';if(location.hash==='#quiz')render({scroll:true});return}
case'export-progress':download(JSON.stringify({version:1,exportedAt:new Date().toISOString(),profile},null,2),'诗光-学习记录.json');return;case'import-progress':$('#progress-import').click();return;case'export-data':download(JSON.stringify({meta,poems},null,2),'诗光-古诗文与原创题库.json');return;default:return}render();window.scrollTo(0,y)});
$('#search').addEventListener('input',e=>{state.search=e.target.value;const route=location.hash.slice(1).split('/')[0];if(!['library','grade','study'].includes(route))location.hash=state.grade?'grade/'+state.grade:'library';else render()});
document.addEventListener('change',async e=>{if(e.target.id==='edition-filter'){state.edition=e.target.value;render()}if(e.target.id==='theme-filter'){state.theme=e.target.value;render()}if(e.target.id==='status-filter'){state.status=e.target.value;render()}if(e.target.id==='book-filter'){state.book=e.target.value;render()}if(e.target.id==='voice-rate')state.speechRate=Number(e.target.value);if(e.target.id==='progress-import'&&e.target.files[0]){try{const imported=JSON.parse(await e.target.files[0].text());if(imported.version!==1||!imported.profile)throw Error('version');const data=imported.profile;if(!['favorites','mastered','visited','wrong'].every(k=>Array.isArray(data[k])))throw Error('schema');for(const k of ['favorites','mastered','visited']){if(!Array.isArray(data[k]))throw Error('schema');profile[k]=[...new Set([...profile[k],...data[k].filter(id=>poemMap.has(id))])]}if(!Array.isArray(data.wrong))throw Error('schema');profile.wrong=[...new Set([...profile.wrong,...data.wrong.filter(id=>qMap.has(id))])];if(data.answers&&typeof data.answers==='object'){for(const [id,a]of Object.entries(data.answers)){const q=qMap.get(id);if(!q||!a||typeof a.checked!=='boolean'||![true,false,null,undefined].includes(a.correct))continue;if(q.type==='choice'&&(!Number.isInteger(a.value)||a.value<0||a.value>=q.options.length))continue;if(q.type!=='choice'&&typeof a.value!=='string')continue;profile.answers[id]=a}}save();toast('记录已导入，与当前记录合并。');render()}catch{toast('文件格式不正确，请选择诗光导出的学习记录。')}}});
document.addEventListener('input',e=>{if(e.target.matches('[data-answer]'))profile.answers[e.target.dataset.answer]={value:e.target.value,checked:false}});
document.addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar')&&!e.target.closest('[data-action="menu"]'))document.body.classList.remove('menu-open')});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}if(e.key==='Escape')document.body.classList.remove('menu-open')});
$('#source-dialog').addEventListener('click',e=>{if(e.target===$('#source-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('hashchange',loadRoute);window.addEventListener('pagehide',()=>{save();stopSpeech()});
loadRoute();
